using System.Diagnostics;
using TextAnalysis;

const int WarmupIterations = 100;
const int BenchmarkIterations = 10_000;

var rng = new Random(42);
var words = new string[1000];
for (int i = 0; i < words.Length; i++)
    words[i] = new string((char)('a' + rng.Next(26)), rng.Next(1, 15));

var small = new TextAnalyzer("The quick brown fox jumps over the lazy dog near the river bank");
var medium = new TextAnalyzer(string.Join(' ', words));

Console.WriteLine($"Runtime: {System.Runtime.InteropServices.RuntimeInformation.FrameworkDescription}");
Console.WriteLine($"{"Method",-35} {"Mean (ns)",12} {"Allocated",12}");
Console.WriteLine(new string('-', 60));

Benchmark("AverageWordLength_Small", () => small.AverageWordLength());
Benchmark("AverageWordLength_Medium", () => medium.AverageWordLength());
Benchmark("WordLengthHistogram_Small", () => small.WordLengthHistogram());
Benchmark("WordLengthHistogram_Medium", () => medium.WordLengthHistogram());
Benchmark("UniqueWordCount_Small", () => small.UniqueWordCount());
Benchmark("UniqueWordCount_Medium", () => medium.UniqueWordCount());

static void Benchmark(string name, Func<object?> action)
{
    // Warmup
    for (int i = 0; i < WarmupIterations; i++) action();

    // Force GC before measurement
    GC.Collect();
    GC.WaitForPendingFinalizers();
    GC.Collect();

    long allocBefore = GC.GetTotalAllocatedBytes(precise: true);
    var sw = Stopwatch.StartNew();
    for (int i = 0; i < BenchmarkIterations; i++) action();
    sw.Stop();
    long allocAfter = GC.GetTotalAllocatedBytes(precise: true);

    double meanNs = (double)sw.Elapsed.TotalNanoseconds / BenchmarkIterations;
    double allocPerOp = (double)(allocAfter - allocBefore) / BenchmarkIterations;

    Console.WriteLine($"{name,-35} {meanNs,12:F1} {allocPerOp,10:F0} B");
}

